using PlayerOne.Windows.Services;namespace PlayerOne.Windows;public partial class SettingsWindow:System.Windows.Window{public SettingsWindow(){InitializeComponent();var x=PlayerSettings.Load();Reconnect.IsChecked=x.AutoReconnect;Background.IsChecked=x.BackgroundPlayback;Subs.IsChecked=x.SubtitlesEnabled;}void Save_Click(object s,System.Windows.RoutedEventArgs e){var old=PlayerSettings.Load();PlayerSettings.Save(old with{AutoReconnect=Reconnect.IsChecked==true,BackgroundPlayback=Background.IsChecked==true,SubtitlesEnabled=Subs.IsChecked==true});Close();}}